"use client";
import { useEffect, useState, type ReactNode } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { BrandMark } from "@/components/landing/brand-mark";
import { Icon, type IconName } from "@/components/organization/icons";
import { clearDemoSession, getDemoSession } from "@/lib/demo-auth";
import styles from "./vendor.module.css";

const primary=[
  ["Overview","/vendor","overview"],["Tender Opportunities","/vendor/opportunities","tenders"],["My Proposals","/vendor/proposals","evaluation"],["Documents & Verification","/vendor/documents","vendors"],["Bid Activity","/vendor/activity","insights"],["Awards & Contracts","/vendor/awards","delivery"],
] as const satisfies ReadonlyArray<readonly [string,string,IconName]>;
const secondary=[["Settings","/vendor/settings","settings"],["Business Profile","/vendor/profile","profile"]] as const satisfies ReadonlyArray<readonly [string,string,IconName]>;

export function VendorShell({children}:{children:ReactNode}){const path=usePathname(),router=useRouter();const[open,setOpen]=useState(false),[ready,setReady]=useState(false);useEffect(()=>{const timer=window.setTimeout(()=>{const session=getDemoSession();if(!session||session.role!=="vendor"){router.replace("/login");return}setReady(true)},0);return()=>window.clearTimeout(timer)},[router]);useEffect(()=>{if(!open)return;const close=(e:KeyboardEvent)=>{if(e.key==="Escape")setOpen(false)};document.addEventListener("keydown",close);return()=>document.removeEventListener("keydown",close)},[open]);if(!ready)return <main className={styles.loading}>Validating vendor workspace…</main>;const context=primary.find(([,href])=>href==="/vendor"?path===href:path.startsWith(href))?.[0]??secondary.find(([,href])=>path.startsWith(href))?.[0]??"Vendor";return <div className={styles.shell}>{open&&<button className={styles.backdrop} aria-label="Close navigation" onClick={()=>setOpen(false)}/>}<aside className={`${styles.sidebar} ${open?styles.open:""}`}><div className={styles.brand}><Link className="wordmark" href="/"><BrandMark/><span>Tender<span className="accent-text">IQ</span></span></Link></div><span className={styles.navLabel}>Vendor workspace</span><nav>{primary.map(([label,href,icon])=><Nav key={href} {...{label,href,icon,path}} close={()=>setOpen(false)}/>)}</nav><div className={styles.bottom}>{secondary.map(([label,href,icon])=><Nav key={href} {...{label,href,icon,path}} close={()=>setOpen(false)} bottom/>)}<button className={styles.bottomLink} onClick={()=>{clearDemoSession();router.replace("/login")}}><Icon name="logout"/>Logout</button></div></aside><div className={styles.main}><header className={styles.topbar}><button className={styles.menu} onClick={()=>setOpen(true)} aria-label="Open navigation"><Icon name="menu"/></button><div className={styles.context}><i/><span>Vendor</span><b>/</b><strong>{context}</strong></div><div className={styles.actions}><button className={styles.search} aria-label="Search workspace"><Icon name="search"/><span>Search tenders and proposals</span></button><button className={styles.icon} aria-label="Notifications"><Icon name="bell"/></button><Link className={styles.account} href="/vendor/profile">AI <span>Apex Infra</span></Link></div></header><main className={styles.content}>{children}</main></div></div>}
function Nav({label,href,icon,path,close,bottom=false}:{label:string;href:string;icon:IconName;path:string;close:()=>void;bottom?:boolean}){const active=href==="/vendor"?path===href:path.startsWith(href);return <Link href={href} onClick={close} className={bottom?styles.bottomLink:`${styles.navLink} ${active?styles.active:""}`} aria-current={active?"page":undefined}><Icon name={icon}/>{label}</Link>}
